&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;Who You Are&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt; &lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;You are a&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;Licensed Practical&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;N&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;urse&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;(LPN)&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;who&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;thrives&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;on&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;connecting with people&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;through&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;compassionate communication.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;You easily build&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;meaningful relationships&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;&amp;nbsp;and support positive behavior change through partnership rather than pressure. Leveraging your practical nursing knowledge and structured care protocols, you help patients clearly understand and follow their provider-directed care plans. You bring grace under pressure and feel energized by supporting high-risk patients as they work toward improved health and stability.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;Who We Are&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;Oasis Health Partners (Oasis) is building healthier communities by advancing primary care.&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt; &lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;&amp;nbsp;We partner with patients,&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;providers&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;&amp;nbsp;and plans to provide personalized, local care for seniors in towns across America.&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt; &lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;&amp;nbsp;We believe that&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;patients’&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;&amp;nbsp;needs come first, and that primary care is the foundation of patient-centric healthcare.&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt; &lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;With Oasis, patients receive better access and care.&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt; &lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;Providers receive the data,&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;resources&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;&amp;nbsp;and&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;expertise&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;&amp;nbsp;to be successful in value-based care arrangements. Pa&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;yors&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;&amp;nbsp;get the benefit of a solution that improves performance, drives&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;growth&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;&amp;nbsp;and reduces the total cost of care in hard-to-engage markets.&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;    &lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;Together, we will boldly advance primary care for those that need it most. We are excited for you to join us on this journey. We invite you to be a part of Oasis, where&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;you’ll&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt; discover we listen first, do the right thing, build things together and go all in --- while having fun!&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt; &lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;Your Role&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;As&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;a&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;High-Risk&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;Care Coordinator&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;,&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;you build trusted, ongoing relationships with high-risk patients through consistent outreach, active listening, and structured clinical support. You regularly engage patients by phone and text to address complex medical and social needs, including medication management, chronic condition monitoring, and barriers to care. Using patient-centered discussion and established care protocols, you support patients in understanding and adhering to provider-directed care plans while&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;identifying&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;&amp;nbsp;emerging risks that require escalation.&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;&amp;nbsp;This role is part of a new high-risk patient&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;management&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;program being built from the ground up. You will have the opportunity to help shape workflows, outreach strategies, and processes that truly work for patients and care teams.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;Additional&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;Responsibilities:&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;•&quot; data-font=&quot;Avenir Book&quot; data-listid=&quot;14&quot; data-list-defn-props=&quot;{&amp;quot;335551671&amp;quot;:0,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Avenir Book&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;0&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;Conduct regularly scheduled outbound outreach to high-risk patients to support ongoing care management, reduce avoidable&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;utilization&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;, and address gaps in care.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;•&quot; data-font=&quot;Avenir Book&quot; data-listid=&quot;14&quot; data-list-defn-props=&quot;{&amp;quot;335551671&amp;quot;:0,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Avenir Book&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;0&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;Contribute to the development of a new high-risk patient &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;management&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;program by helping design, test, and refine outreach workflows, documentation practices, and care coordination processes in a growing, non–enterprise EHR environment.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;•&quot; data-font=&quot;Avenir Book&quot; data-listid=&quot;14&quot; data-list-defn-props=&quot;{&amp;quot;335551671&amp;quot;:0,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Avenir Book&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;0&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;Perform medication reconciliation and &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;adherence&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;&amp;nbsp;support by reviewing patient-reported medication use,&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;identifying&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;&amp;nbsp;discrepancies, and escalating concerns to the RN or Provider.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;•&quot; data-font=&quot;Avenir Book&quot; data-listid=&quot;14&quot; data-list-defn-props=&quot;{&amp;quot;335551671&amp;quot;:0,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Avenir Book&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;0&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;Collect, assess, and document patient-reported symptoms, condition trends, risk indicators, and barriers to adherence within LPN scope of practice.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;•&quot; data-font=&quot;Avenir Book&quot; data-listid=&quot;14&quot; data-list-defn-props=&quot;{&amp;quot;335551671&amp;quot;:0,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Avenir Book&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;0&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;Provide disease-specific education, self-management reinforcement, and motivational coaching using approved materials and care pathways.&lt;/span&gt;&lt;/li&gt;
